/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { rm } from 'node:fs/promises';
import { once } from 'node:events';
import { join } from 'node:path';

const profile = mkdtempSync(join(process.cwd(), '.chrome-acceptance-'));
const child = spawn('google-chrome', ['--headless', '--no-sandbox', '--disable-dev-shm-usage', '--disable-background-networking', '--disable-component-update', '--disable-sync', '--no-first-run', '--no-default-browser-check', '--proxy-server=http://127.0.0.1:1', '--proxy-bypass-list=127.0.0.1:41639', '--remote-debugging-pipe', '--user-data-dir='+profile, 'about:blank'], {stdio: ['ignore','ignore','ignore','pipe','pipe']});
let buffer = '';
let id = 0;
const pending = new Map();
child.stdio[4].setEncoding('utf8').on('data', chunk => {
  buffer += chunk;
  const messages = buffer.split('\\0');
  buffer = messages.pop();
  for (const message of messages) {
    const packet = JSON.parse(message);
    pending.get(packet.id)?.(packet);
  }
});
function send(method, params = {}, sessionId) {
  return new Promise((resolve, reject) => {
    const request = ++id;
    pending.set(request, ({result,error}) => {
      pending.delete(request);
      if (error) reject(Error(JSON.stringify(error)));
      else resolve(result);
    });
    child.stdio[3].write(JSON.stringify({id: request, method, params, sessionId})+'\\0');
  });
}
const deadline = setTimeout(() => child.kill(), 12000);
try {
  const {targetId} = await send('Target.createTarget', {url:'about:blank'});
  const {sessionId} = await send('Target.attachToTarget',{targetId,flatten:true});
  const tab = (method, params) => send(method, params, sessionId);
  const evaluate = async expression => (await tab('Runtime.evaluate',{expression,returnByValue:true})).result.value;
  async function waitFor(expression) {
    for (let n=0;n<60;n++) {
      const result = await evaluate(expression);
      if (result) return result;
      await new Promise(resolve=>setTimeout(resolve,100));
    }
    throw Error('Page condition timed out: '+expression);
  }
  await tab('Page.navigate',{url:'http://127.0.0.1:41639/it/'});
  const link = \"[...document.links].find(a => a.textContent.trim() === 'Manuale del turno 2.0')\";
  console.log(await waitFor("'`document.documentElement.dataset.hasHydrated === '"'true' && ("'${link})?.href`));
  await evaluate(`(${link}).click()`);
  console.log(await waitFor("document.querySelector('"'article h1') && JSON.stringify({url:location.href,lang:document.documentElement.lang,text:document.querySelector('article').innerText})\"));
} finally {
  clearTimeout(deadline);
  const closed = once(child, 'close');
  child.kill();
  await closed;
  await rm(profile,{recursive:true});
}
JS"

